Method.Source:
/// <summary>
/// Populates the SalesInvoiceHeaderFooterTmp table with additional AVA fields.
/// </summary>
/// <param name="_custInvoiceJour">The CustInvoiceJour record to use for population.</param>
/// <param name="_companyInfo">The CompanyInfo record to use for population.</param>
protected void populateSalesInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
{
    next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);

    // Set additional AVA fields from CustInvoiceJour
    salesInvoiceHeaderFooterTmp.AVADlvMode             = _custInvoiceJour.DlvMode;
    salesInvoiceHeaderFooterTmp.AVADlvTerm             = _custInvoiceJour.DlvTerm;
    salesInvoiceHeaderFooterTmp.AVAWorkerSalesTaker    = _custInvoiceJour.WorkerSalesTaker;
    salesInvoiceHeaderFooterTmp.AVAProforma            = _custInvoiceJour.isProforma();
}

    /// <summary>
    /// Populates the invoice detail information into the <c>SalesInvoiceTmp</c> table buffer.
    /// </summary>
    /// <param name="_custInvoiceJour">
    /// The <c>CustInvoiceJour</c> record that has the invoice header information.
    /// </param>
    /// <param name="_custInvoiceTrans">
    /// The <c>CustInvoiceTrans</c> record that has the invoice details information.
    /// </param>
    /// <param name="_taxSpec">
    /// The <c>TaxSpec</c> class instance that has the taxes information.
    /// </param>
    /// <param name="_custPaymSchedLine">
    /// The <c>CustPaymSchedLine</c> record that has the payment schedules information.
    /// </param>
    /// <param name="_prepaymentCustTrans">
    /// The <c>CustTrans</c> record that has the prepayment information.
    /// </param>
    /// <param name="_prepaymentTaxTrans">
    /// The <c>TaxTrans</c> record that has the prepayment taxes information.
    /// </param>
    protected void populateSalesInvoiceTmp(CustInvoiceJour          _custInvoiceJour,
                                            CustInvoiceTrans        _custInvoiceTrans,
                                            TaxSpec                 _taxSpec,
                                            CustPaymSchedLine       _custPaymSchedLine,
                                            CustTrans               _prepaymentCustTrans,
                                            TaxTrans                _prepaymentTaxTrans)
	{
        next populateSalesInvoiceTmp(_custInvoiceJour, _custInvoiceTrans, _taxSpec, _custPaymSchedLine, _prepaymentCustTrans, _prepaymentTaxTrans);

        //Markuptrans will fill in AvaReportingMarkupTransTmp in the insert method
        salesInvoiceTmp.AVACustInvoiceTrans = _custInvoiceTrans.recid;
        salesInvoiceTmp.AVAPriceUnit        = _custInvoiceTrans.PriceUnit;
        SalesInvoiceTmp.AVALineNum          = _custInvoiceTrans.LineNum;
        SalesInvoiceTmp.AVAInventTransId    = _custInvoiceTrans.InventTransId;
    }
